/**
 * Project the multilingual ENTITY DESIGNATOR register into TypeScript, so the
 * intake can pre-fill organisation type from the name the founder already
 * typed — on the client, with no network call and no second register.
 *
 * FREE. Writes lib/intelligence/organisationDesignators.generated.ts.
 *
 * ── Why a generated file and not a literal ────────────────────────────────
 * `ETL/lib/merge_stoplist.py` already carries this register. It was built for
 * the merge pipeline from the opposite side of the same fact: a token that must
 * NEVER anchor a brand match is exactly a token that names a KIND rather than
 * an entity. Copying it into TypeScript would be the "keep in sync" comment
 * this repo has been burned by three times, and the ETL file is not deployed
 * with the frontend, so it cannot simply be read at runtime.
 *
 * ── Why the GROUPING lives here and the TOKENS do not ─────────────────────
 * The Python register is a flat set: it knows these tokens are generic, not
 * which kind each names. The grouping below is the derived property applied
 * (see lib/intelligence/organisationType.ts for the property and its test),
 * and every token in it is ASSERTED to exist in the Python register. A token
 * that has drifted out of that file fails this script rather than silently
 * becoming a local invention.
 *
 * Run: npx tsx scripts/emit_org_designators.ts
 */
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const ROOT = resolve(process.cwd(), "../capital");
export const SOURCE = resolve(ROOT, "ETL/lib/merge_stoplist.py");
export const OUT = resolve(process.cwd(), "lib/intelligence/organisationDesignators.generated.ts");

/**
 * Designator -> organisation type. Ordered most specific first: a name carrying
 * both a purpose word and a company form ("<name> Forschung GmbH") is the
 * purpose body, because incorporating as a company is HOW a public-purpose body
 * is constituted in several jurisdictions, and the purpose word is the
 * discriminating one.
 */
export const KIND_ORDER = ["public_body", "research_org", "nonprofit", "company"] as const;

export const DESIGNATORS: Record<(typeof KIND_ORDER)[number], string[]> = {
  public_body: ["comune", "commune", "ayuntamiento", "gemeinde", "kommune",
    "departement", "agglomeration", "metropole", "municipal", "ente", "agence",
    "agenzia", "agencia", "chambre", "camera", "chamber"],
  research_org: ["universita", "universite", "universidad", "universitat",
    "university", "uniwersytet", "univerzita", "ulikool", "hochschule", "ecole",
    "scuola", "escuela", "schule", "institut", "instituto", "institutul",
    "istituto", "cercetare", "ricerca", "investigacion", "recherche",
    "forschung", "vyzkumny", "ustav", "badawcza"],
  nonprofit: ["association", "associazione", "asociacion", "asbl", "fondation",
    "fondazione", "fundacion", "fundacio", "fundacja", "stiftung", "foundation",
    "cooperativa", "cooperative", "cooperatie", "kooperativ", "coop", "druzstvo",
    "vereniging", "syndicat", "sindicato", "federation", "federazione", "verband",
    "consorzio", "consorcio", "vsi"],
  company: ["gmbh", "mbh", "ag", "kg", "kgaa", "ohg", "gbr", "ug", "se", "eg",
    "gesmbh", "sa", "sas", "sasu", "sarl", "sca", "snc", "scs", "sci", "eurl",
    "srl", "srls", "spa", "sapa", "scarl", "scrl", "sl", "slu", "slne", "sau",
    "slp", "lda", "sgps", "scl", "bv", "nv", "cv", "vof", "cvba", "bvba", "oy",
    "oyj", "ab", "asa", "aps", "ks", "hf", "ehf", "ltd", "limited", "plc", "llp",
    "llc", "inc", "corp", "teoranta", "kft", "zrt", "bt", "nyrt", "kkt", "spzoo",
    "zoo", "sro", "spol", "doo", "dd", "ood", "ad", "eood", "uab", "sia", "ou",
    "as", "ase", "doel", "spk", "spj", "ska", "akz", "pfa", "sociedad", "anonima",
    "limitada", "sociedade", "sabiedriba", "akcine", "bendrove"],
};

/** Every token the shared Python register declares generic, in one set. */
export function sharedRegister(): Set<string> {
  const src = readFileSync(SOURCE, "utf8");
  const out = new Set<string>();
  for (const name of ["LEGAL", "ORG", "GEO"]) {
    const m = new RegExp(`^${name}\\s*=\\s*\\{([\\s\\S]*?)^\\}`, "m").exec(src);
    if (!m) throw new Error(`${name} not found in ${SOURCE} — the shared register moved`);
    for (const t of m[1].matchAll(/"([^"]+)"/g)) out.add(t[1]);
  }
  return out;
}

export function build(): string {
  const shared = sharedRegister();
  const invented = Object.values(DESIGNATORS).flat().filter((t) => !shared.has(t));
  if (invented.length) {
    throw new Error(
      `these designators are absent from ETL/lib/merge_stoplist.py and would be a ` +
      `second, local register: ${invented.join(", ")}`);
  }
  const body = KIND_ORDER.map((k) =>
    `  ${k}: ${JSON.stringify(DESIGNATORS[k])},`).join("\n");
  return `// GENERATED by web/scripts/emit_org_designators.ts from
// ETL/lib/merge_stoplist.py. Do not edit by hand — regenerate.
//
// The multilingual entity designators, grouped by the kind each one names.
// Every token here is asserted at generation time to exist in the shared
// register, so this file can never become a second source of truth.
//
// Ordered most specific first; see organisationType.ts for the property.
export const ORG_DESIGNATOR_ORDER = ${JSON.stringify(KIND_ORDER)} as const;

export const ORG_DESIGNATORS: Record<string, readonly string[]> = {
${body}
};
`;
}

if (process.argv[1]?.endsWith("emit_org_designators.ts")) {
  writeFileSync(OUT, build());
  console.log(`wrote ${OUT} (${Object.values(DESIGNATORS).flat().length} designators)`);
}
